INSERT INTO cases (id, case_number, title, status, data_json) VALUES ('courtcase-3', 'D-1-DC-26-301874', 'The State of Texas v. Cody Ray Brennan', 'active', '{"id":"courtcase-3","caption":"The State of Texas v. Cody Ray Brennan","caseNumber":"D-1-DC-26-301874","court":"427th District Court, Travis County, Texas","burden":"All persons are presumed to be innocent, and no person may be convicted of an offense unless each element of the offense is proved beyond a reasonable doubt. The fact that a person has been arrested, confined, indicted or otherwise charged gives rise to no inference of guilt. The State has the burden of proving the defendant guilty, and it must do so by proving each and every element of the offense charged beyond a reasonable doubt. If it fails to do so, you must acquit the defendant. Your verdict on each count must be unanimous.","counts":[{"id":"c1","label":"Count 1: Intoxication Assault","statute":"Texas Penal Code § 49.07(a)(1) (third-degree felony)","summary":"A person commits intoxication assault if the person, by accident or mistake, while operating a motor vehicle in a public place while intoxicated, by reason of that intoxication causes serious bodily injury to another.","elements":["The defendant, Cody Ray Brennan, on or about June 6, 2026, in Travis County, Texas, operated a motor vehicle: a gray 2019 Ford F-150 pickup.","He operated it in a public place: Cedar Hollow Road near Bluff Creek Drive.","He was intoxicated while operating it.","By reason of that intoxication, he caused serious bodily injury to Lucía Ferrer by accident or mistake, by striking her bicycle with the pickup."],"definitions":[{"term":"Intoxicated","text":"(A) Not having the normal use of mental or physical faculties by reason of the introduction of alcohol, a controlled substance, a drug, a dangerous drug, a combination of two or more of those substances, or any other substance into the body; or (B) having an alcohol concentration of 0.08 or more. Texas Penal Code § 49.01(2). You may find either one."},{"term":"Alcohol concentration","text":"The number of grams of alcohol per 210 liters of breath, per 100 milliliters of blood, or per 67 milliliters of urine. Texas Penal Code § 49.01(1). The State must prove the defendant was intoxicated at the time he was operating the vehicle, not only when his blood was drawn."},{"term":"Serious bodily injury","text":"Bodily injury that creates a substantial risk of death or that causes death, serious permanent disfigurement, or protracted loss or impairment of the function of any bodily member or organ. Texas Penal Code § 1.07(a)(46)."},{"term":"Public place","text":"Any place to which the public or a substantial group of the public has access, including streets and highways. Texas Penal Code § 1.07(a)(40)."},{"term":"Operate","text":"A person operates a motor vehicle when, under the totality of the circumstances, he takes action to affect the functioning of the vehicle in a manner that would enable its use."},{"term":"Causation","text":"A person is criminally responsible if the result would not have occurred but for his conduct, operating either alone or concurrently with another cause, unless the concurrent cause was clearly sufficient to produce the result and the conduct of the actor clearly insufficient. Texas Penal Code § 6.04(a)."}]},{"id":"c2","label":"Count 2: Accident Involving Injury (Failure to Stop and Render Aid)","statute":"Texas Transportation Code §§ 550.021, 550.023 (third-degree felony where serious bodily injury results)","summary":"The operator of a vehicle involved in an accident that results, or is reasonably likely to result, in injury to a person must immediately stop at or as close as possible to the scene, determine whether anyone needs aid, and remain until giving his information and rendering reasonable assistance.","elements":["The defendant was operating a vehicle involved in an accident on Cedar Hollow Road on or about June 6, 2026.","The accident resulted in injury to Lucía Ferrer.","The defendant knew that the accident had occurred.","The defendant intentionally or knowingly failed to stop at the scene, or as close to it as possible, and remain there until he had given his name, address, vehicle registration and insurance information and rendered reasonable assistance to the injured person."],"definitions":[{"term":"Reasonable assistance","text":"Including transporting, or making arrangements for transporting, the injured person to a physician or hospital for medical treatment if it is apparent that treatment is necessary or if the injured person requests it. Texas Transportation Code § 550.023(3)."},{"term":"Knowingly","text":"A person acts knowingly with respect to the nature of his conduct or to circumstances surrounding his conduct when he is aware of the nature of his conduct or that the circumstances exist. Texas Penal Code § 6.03(b). You may infer knowledge from his acts, words and conduct."}]},{"id":"c3","label":"Lesser-Included Offense of Count 1: Driving While Intoxicated","statute":"Texas Penal Code § 49.04(a) (Class B misdemeanor)","summary":"A person commits an offense if the person is intoxicated while operating a motor vehicle in a public place. Consider this count only if you find the defendant not guilty of Count 1, or if you have a reasonable doubt that he caused the serious bodily injury by reason of intoxication.","elements":["The defendant, on or about June 6, 2026, in Travis County, Texas, operated a motor vehicle.","He operated it in a public place: Cedar Hollow Road.","He was intoxicated while operating it."],"definitions":[{"term":"Intoxicated","text":"The same meaning as in Count 1: not having the normal use of mental or physical faculties by reason of the introduction of alcohol into the body, or having an alcohol concentration of 0.08 or more."}]}],"status":"active","jury":{"seats":[]}}');
INSERT INTO cases (id, case_number, title, status, data_json) VALUES ('courtcase-1', '26-CR-0418', 'People v. Dana Whitlock', 'active', '{"id":"courtcase-1","caption":"People v. Dana Whitlock","caseNumber":"26-CR-0418","court":"Millbrook County Superior Court, Part 3","burden":"The People must prove every element of a count beyond a reasonable doubt. If they have not proven any one element, you must find the defendant not guilty of that count. You must also be convinced that it was the defendant who committed the acts.","counts":[{"id":"c1","label":"Count 1: Burglary in the Third Degree","statute":"Millbrook Penal Code § 140.20","summary":"A person is guilty of burglary in the third degree when they knowingly enter or remain unlawfully in a building with intent to commit a crime inside it.","elements":["The defendant entered or remained in a building: Callan''s Hardware, 412 Ferris Street.","The entry or remaining was unlawful: the defendant had no license or privilege to be there at that time.","The defendant knew that the entry or remaining was unlawful.","When entering or remaining, the defendant intended to commit a crime inside (here, theft)."],"definitions":[{"term":"Enter or remain unlawfully","text":"To be in a building without permission from the owner or anyone authorized to give it. A former employee has no permission outside working hours."},{"term":"Intent","text":"A conscious aim or objective. You may infer intent from what a person did and the surrounding circumstances."}]},{"id":"c2","label":"Count 2: Grand Larceny in the Fourth Degree","statute":"Millbrook Penal Code § 155.30","summary":"A person is guilty of grand larceny in the fourth degree when they steal property and the value of the property exceeds $1,000.","elements":["The defendant wrongfully took, obtained or withheld property.","The property belonged to someone else: Callan''s Hardware.","The defendant did so with intent to deprive the owner of the property or to keep it for themselves or another person.","The value of the property taken exceeded $1,000."],"definitions":[{"term":"Value","text":"The market value of the property at the time and place of the theft. Repair costs for damage are not counted toward the value of property taken."},{"term":"Deprive","text":"To withhold property permanently, or for so long that most of its value or benefit is lost to the owner."}]},{"id":"c3","label":"Count 3: Criminal Mischief in the Fourth Degree","statute":"Millbrook Penal Code § 145.00","summary":"A person is guilty of criminal mischief in the fourth degree when, having no right to do so nor any reasonable ground to believe they have such a right, they intentionally damage the property of another person.","elements":["The defendant damaged property: the rear service door of Callan''s Hardware.","The property belonged to someone else.","The defendant acted intentionally, not by accident.","The defendant had no right to damage the property and no reasonable ground to believe they had that right."],"definitions":[{"term":"Damage","text":"Any physical harm that impairs the value or usefulness of the property, such as pry marks that break a lock or frame."}]}],"status":"active","jury":{"seats":[]}}');
INSERT INTO cases (id, case_number, title, status, data_json) VALUES ('courtcase-2', '26-CR-0533', 'People v. Rafael Alvarez', 'active', '{"id":"courtcase-2","caption":"People v. Rafael Alvarez","caseNumber":"26-CR-0533","court":"Millbrook County Superior Court, Part 1","burden":"The People must prove every element of a count beyond a reasonable doubt. If they have not proven any one element, you must find the defendant not guilty of that count. You must also be convinced that it was the defendant who committed the acts.","counts":[],"status":"active","jury":{"seats":[]}}');
