INSERT INTO exhibits (id, case_id, r2_key, filename, content_type, size, checksum, visibility, uploader_id, number, title, party, description, type, status, lines_json) VALUES ('ex_ae84b2405a9b', 'courtcase-3', 'exhibits/file_4b05aa858bfe.pdf', 'D-2.pdf', 'application/pdf', 2359, NULL, 'case', 'D-1-DC-26-301874-bailiff-01', 'D-2', 'Toxicology consultation report', 'defense', 'Dr. A. Whitcomb on retrograde extrapolation and drinking after driving.', 'pdf', 'admitted', NULL);
INSERT INTO exhibits (id, case_id, r2_key, filename, content_type, size, checksum, visibility, uploader_id, number, title, party, description, type, status, lines_json) VALUES ('ex_fe82f0336c7f', 'courtcase-3', 'exhibits/file_286e7be35f90.txt', 'Tr-1.txt', 'text/plain; charset=utf-8', 2476, NULL, 'case', 'D-1-DC-26-301874-bailiff-01', 'Tr-1', 'Transcript: Deputy Hannah Kowalski', 'court', 'Direct and cross-examination.', 'transcript', 'admitted', '[{"n":1,"speaker":"THE CLERK","text":"Testimony of Deputy Hannah Kowalski, Travis County Sheriff''s Office. Direct examination by Assistant District Attorney Aldana."},{"n":2,"speaker":"Q","text":"Deputy Kowalski, what were you doing on the night of June 6th?"},{"n":3,"speaker":"A","text":"I was on patrol in the western district, which covers Cedar Hollow Road."},{"n":4,"speaker":"Q","text":"What call did you receive?"},{"n":5,"speaker":"A","text":"At 11:49 p.m. dispatch put out a crash involving a cyclist on Cedar Hollow near Bluff Creek Drive, with the striking vehicle leaving eastbound."},{"n":6,"speaker":"Q","text":"What did the caller describe?"},{"n":7,"speaker":"A","text":"A gray or silver full-size pickup, partial Texas plate beginning L-K-T."},{"n":8,"speaker":"Q","text":"What did you do?"},{"n":9,"speaker":"A","text":"EMS was already en route, so I ran the partial plate against gray pickups registered nearby. One came back to Cody Brennan, 1.6 miles east of the scene."},{"n":10,"speaker":"Q","text":"When did you get to that address?"},{"n":11,"speaker":"A","text":"12:31 a.m. The pickup was in the driveway. The hood was still warm."},{"n":12,"speaker":"Q","text":"What did you see on the truck?"},{"n":13,"speaker":"A","text":"Fresh damage to the right front fender, and the right side mirror was broken off its mount. That is State''s Exhibit S-3."},{"n":14,"speaker":"Q","text":"Did you speak with the defendant?"},{"n":15,"speaker":"A","text":"Yes, at the front door. I asked if he had been driving on Cedar Hollow. He said yes, and that he thought he had hit a deer or a branch."},{"n":16,"speaker":"Q","text":"Did you notice anything about him?"},{"n":17,"speaker":"A","text":"A strong odor of an alcoholic beverage, slurred speech, and red, glassy eyes. He used the door frame to steady himself."},{"n":18,"speaker":"Q","text":"Did he say whether he had been drinking?"},{"n":19,"speaker":"A","text":"He said he had a couple of beers at the Rusty Spur, and then one drink at home to calm his nerves after he got back."},{"n":20,"speaker":"Q","text":"Did you perform field sobriety tests?"},{"n":21,"speaker":"A","text":"Yes. On horizontal gaze nystagmus I observed six of six clues. On the walk and turn, five of eight. On the one leg stand, three of four."},{"n":22,"speaker":"Q","text":"Did he give a breath sample?"},{"n":23,"speaker":"A","text":"He refused. I obtained a search warrant, and his blood was drawn at 2:41 a.m."},{"n":24,"speaker":"Q","text":"Nothing further. Cross-examination by Mr. Kessler."},{"n":25,"speaker":"Q","text":"Deputy, when you walked into the kitchen, what was on the counter?"},{"n":26,"speaker":"A","text":"An open bottle of whiskey and a glass with some liquid in it."},{"n":27,"speaker":"Q","text":"That is Defense Exhibit D-1, the still from your body camera?"},{"n":28,"speaker":"A","text":"Yes."},{"n":29,"speaker":"Q","text":"You did not see my client drinking before he drove, did you?"},{"n":30,"speaker":"A","text":"No, I did not."},{"n":31,"speaker":"Q","text":"And you don''t know how much he poured after he got home?"},{"n":32,"speaker":"A","text":"Only what he told me. He said one drink."},{"n":33,"speaker":"Q","text":"The bicycle at the scene. Was its rear light on when you inspected it?"},{"n":34,"speaker":"A","text":"The switch was in the off position when I looked at it, after EMS had moved it."},{"n":35,"speaker":"Q","text":"Thank you. Nothing further."},{"n":36,"speaker":"THE COURT","text":"The witness may step down."}]');
INSERT INTO exhibits (id, case_id, r2_key, filename, content_type, size, checksum, visibility, uploader_id, number, title, party, description, type, status, lines_json) VALUES ('ex_c310e219cdca', 'courtcase-3', 'exhibits/file_eb330f66a970.txt', 'Tr-2.txt', 'text/plain; charset=utf-8', 1644, NULL, 'case', 'D-1-DC-26-301874-bailiff-01', 'Tr-2', 'Transcript: Darnell Price (eyewitness)', 'court', 'Direct and cross-examination.', 'transcript', 'admitted', '[{"n":1,"speaker":"THE CLERK","text":"Testimony of Darnell Price. Direct examination by Assistant District Attorney Aldana."},{"n":2,"speaker":"Q","text":"Mr. Price, where were you at about 11:45 on the night of June 6th?"},{"n":3,"speaker":"A","text":"Driving home westbound on Cedar Hollow Road, coming up on Bluff Creek Drive."},{"n":4,"speaker":"Q","text":"Was anyone else on the road?"},{"n":5,"speaker":"A","text":"A cyclist on the eastbound shoulder, and a pickup coming up behind her eastbound."},{"n":6,"speaker":"Q","text":"How could you see the cyclist?"},{"n":7,"speaker":"A","text":"My headlights picked her up. She had a reflective vest on, the yellow kind."},{"n":8,"speaker":"Q","text":"What did you see the pickup do?"},{"n":9,"speaker":"A","text":"It drifted right, over the white line onto the shoulder, and the front corner hit her. She went off into the grass."},{"n":10,"speaker":"Q","text":"Was it going fast?"},{"n":11,"speaker":"A","text":"Not crazy fast. Maybe the speed limit. It just drifted."},{"n":12,"speaker":"Q","text":"What did the pickup do after that?"},{"n":13,"speaker":"A","text":"The brake lights came on for a second, maybe two, and then it kept going east."},{"n":14,"speaker":"Q","text":"What did you do?"},{"n":15,"speaker":"A","text":"I turned around, called 911, and stayed with her until EMS came. I gave them the first three letters of the plate, L-K-T."},{"n":16,"speaker":"Q","text":"How was she?"},{"n":17,"speaker":"A","text":"She was conscious, but her leg was bent wrong. She kept asking about her bike."},{"n":18,"speaker":"Q","text":"Nothing further. Cross-examination by Mr. Kessler."},{"n":19,"speaker":"Q","text":"Mr. Price, it was dark out there?"},{"n":20,"speaker":"A","text":"Yes. There are no streetlights on that stretch."},{"n":21,"speaker":"Q","text":"Did you see a red light on the back of the bicycle?"},{"n":22,"speaker":"A","text":"I was coming from the other direction. I could not see the back of it."},{"n":23,"speaker":"Q","text":"So you don''t know if the rear light was on?"},{"n":24,"speaker":"A","text":"No, sir."},{"n":25,"speaker":"Q","text":"You were looking into the pickup''s headlights the whole time?"},{"n":26,"speaker":"A","text":"Mostly, yes."},{"n":27,"speaker":"Q","text":"You didn''t see who was driving?"},{"n":28,"speaker":"A","text":"No. I couldn''t see inside the truck."},{"n":29,"speaker":"Q","text":"Thank you. Nothing further."},{"n":30,"speaker":"THE COURT","text":"You may step down, Mr. Price. Thank you."}]');
